insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('GA', 'GA-CSS-P', 'Contribution spéciale de solidarité sur achats, 1 %, non récupérable', '{}'::jsonb, 'CSS facturée par un fournisseur gabonais, part du coût de l''achat', 'percent', 1, 'purchase', 'domestic', date '2017-01-01', null, 'Textes fiscaux non codifiés annexés au Code général des impôts, art. 25 — taux de 1 % ; art. 32 nouveau (LFR 2017) — le montant acquitté au titre de la CSS est déductible pour la détermination du bénéfice imposable à l''impôt sur les sociétés ou à l''IRPP, ce qui est une déductibilité de charge et non un mécanisme de crédit de CSS sur CSS comme en matière de TVA : aucun texte lu n''ouvre de droit à récupération de la CSS supportée sur un achat. Ce pack ne modèle pas la retenue à la source de l''article 26, alinéa 3 (la CSS facturée à un client assujetti à la TVA est retenue à la source par ce dernier) : voir le README du pack', null, null, 200, 'other', false, '{}'::tax_condition[], null, false, false, null, 'cgi-2019', null, null, null, null),
  ('GA', 'GA-CSS-S', 'Contribution spéciale de solidarité sur ventes, 1 %', '{}'::jsonb, 'CSS collectée sur les opérations imposables, hors TVA et hors CSS elle-même', 'percent', 1, 'sale', 'domestic', date '2017-01-01', null, 'Textes fiscaux non codifiés annexés au Code général des impôts, art. 13 — CSS instituée à compter du 1er janvier 2017 ; art. 14 — redevables les personnes physiques et morales dont le chiffre d''affaires annuel hors taxes atteint au moins 30 000 000 FCFA ; art. 15 et 16 — opérations imposables, notamment les livraisons de biens et les prestations de services ; art. 24 nouveau (LFR 2017) — base imposée hors TVA et hors CSS ; art. 25 — taux de 1 %, arrondi au millier de francs inférieur. L''article 248 nonies, créé par la loi de finances rectificative 2026, y soumet aussi les plateformes numériques non-résidentes, ce qui confirme que ce régime de 2017 reste en vigueur. Ce pack ne modèle pas la retenue à la source de l''article 26 (voir le README du pack) : le compte 446 encaisse la CSS comme si elle était payée normalement par le client', null, null, 90, 'other', true, array['seller_threshold']::tax_condition[], null, false, false, null, 'cgi-2019', null, null, null, null),
  ('GA', 'GA-P-10', 'Achats taux réduit 10 %', '{}'::jsonb, null, 'percent', 10, 'purchase', 'domestic', date '2016-01-01', null, 'Code général des impôts, art. 221 nouveau (LF 2016) pour le taux, déjà applicable aux pièces détachées automobiles, essieux automobiles, carreaux de construction et pointes ; art. 222 et 223 pour la déduction', 'S', null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi-2019', null, null, null, null),
  ('GA', 'GA-P-18', 'Achats de biens 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2016-01-01', null, 'Code général des impôts, art. 221 nouveau (LF 2016) pour le taux ; art. 222 alinéa 2 nouveau (loi de finances rectificative 2026) — le droit à déduction prend naissance lorsque la taxe devient exigible chez le fournisseur, une règle déjà posée par l''art. 222 nouveau (LF 2014) ; art. 223 nouveau — depuis la loi rectificative 2026, seule la TVA figurant distinctement sur une facture électronique normalisée, ou un document en tenant lieu, est déductible', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi-2019', null, null, null, null),
  ('GA', 'GA-P-18-IMMO', 'Immobilisations 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2016-01-01', null, 'Code général des impôts, art. 221 nouveau (LF 2016) pour le taux ; art. 222 nouveau (LF 2014) — la TVA ayant grevé en amont les éléments du prix d''une opération imposable, immobilisations comprises, est déductible ; art. 222 alinéa 6 nouveau (loi de finances rectificative 2026) — exception : la taxe ayant grevé des immobilisations déjà détenues par une entreprise qui devient redevable de la TVA n''ouvre pas droit à déduction ; art. 230 alinéa 1 nouveau — régularisation d''un cinquième par année ou fraction d''année si le bien sort de l''actif ou change d''affectation avant la fin de la quatrième année suivant l''acquisition', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi-2019', null, null, null, null),
  ('GA', 'GA-P-18-ND', 'Achat 18 % non déductible (art. 224, 225)', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2016-01-01', null, 'Code général des impôts, art. 224 nouveau (LF 2016) — n''ouvre pas droit à déduction la taxe ayant grevé notamment les dépenses de logement, hébergement, restauration, réception, spectacle et transport de personnes (sauf pour les professionnels de ces activités), les produits pétroliers hors combustible fixe d''usine, les biens cédés sans rémunération suffisante et les services afférents à des biens exclus du droit à déduction ; art. 225 — n''ouvre pas non plus droit à déduction la TVA sur les véhicules et engins conçus pour le transport de personnes ou à usage mixte constituant des immobilisations, ni sur leur location, leurs pièces détachées ou les services afférents, sauf les exceptions qu''il énumère (véhicules mixtes marchandises/personnes, cars de plus de dix places pour le personnel, parc des loueurs et transporteurs publics). La taxe est une part du coût de ce qui a été acheté', 'S', null, 170, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'cgi-2019', null, null, null, null),
  ('GA', 'GA-P-18-SRV', 'Services extérieurs 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2016-01-01', null, 'Code général des impôts, art. 221 nouveau (LF 2016) pour le taux ; art. 222 alinéa 2 nouveau — déduction après exigibilité chez le fournisseur, soit, pour un service, après son encaissement par le prestataire ; art. 223 nouveau', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi-2019', null, null, null, null),
  ('GA', 'GA-P-3', 'Achats taux réduit 3 %', '{}'::jsonb, null, 'percent', 3, 'purchase', 'domestic', date '2026-07-17', null, 'Code général des impôts, art. 221 nouveau, 4) pour le taux (fer à béton fabriqué au Gabon) ; art. 222 et 223 pour la déduction', 'S', null, 160, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'lfr-2026', null, null, null, null),
  ('GA', 'GA-P-5', 'Achats taux réduit 5 %', '{}'::jsonb, null, 'percent', 5, 'purchase', 'domestic', date '2026-07-17', null, 'Code général des impôts, art. 221 nouveau, 3) pour le taux ; art. 222 et 223 pour la déduction', 'S', null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'lfr-2026', null, null, null, null),
  ('GA', 'GA-P-IMP-18', 'Importation 18 % (TVA acquittée en douane)', '{}'::jsonb, null, 'percent', 18, 'purchase', 'import', date '2019-01-01', null, 'Code général des impôts, art. 221 nouveau (LF 2016) pour le taux, applicable aux biens importés comme aux biens produits localement ; art. 212 et 213 — fait générateur et exigibilité de la TVA à l''importation lors de la mise à la consommation ; art. 238 nouveau (LF 2019) — la TVA à l''importation est liquidée par l''administration des douanes et doit être déclarée et versée avant l''enlèvement de la marchandise ; les documents douaniers justifient la déduction', null, null, 180, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi-2019', null, null, null, null),
  ('GA', 'GA-P-NR-18-ND', 'Services d''un prestataire étranger 18 %, TVA retenue à la source, non déductible', '{}'::jsonb, null, 'percent', 18, 'purchase', 'foreign_services_received', date '2016-01-01', null, 'Code général des impôts, art. 240 — pour les redevables non-résidents, la TVA retenue à la source est payée par le client pour le compte de la personne n''ayant pas au Gabon d''établissement stable ni d''installation professionnelle permanente ; art. 224 nouveau, dernier alinéa — n''ouvre pas droit à déduction la TVA sur les services disponibles sur le territoire national rendus par un prestataire étranger. La taxe retenue et versée par le client devient une part du coût du service', null, null, 190, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'cgi-2019', null, null, null, null),
  ('GA', 'GA-S-0-EXP', 'Exportations et opérations assimilées, taux zéro', '{}'::jsonb, 'Exportations, transports internationaux, avitaillement en carburant, entretien et réparation des aéronefs et navires du trafic international', 'percent', 0, 'sale', 'export', date '2016-01-01', null, 'Code général des impôts, art. 221 nouveau (LF 2016) — taux zéro déjà applicable aux exportations, aux transports internationaux, aux opérations d''avitaillement en carburant et aux opérations d''entretien et réparation effectuées sur les aéronefs et navires affectés au trafic international, dans les mêmes termes ; art. 221 nouveau, 5), alinéa 1 et 6) (loi de finances rectificative 2026) — la rédaction en vigueur depuis le 17 juillet 2026, inchangée sur ce point, précise que ce taux comme les autres s''applique à une base hors TVA', 'G', null, 60, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'cgi-2019', null, null, null, null),
  ('GA', 'GA-S-0-SRV', 'Prestations dont le lieu d''imposition est hors du Gabon, taux zéro', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2026-07-17', null, 'Code général des impôts, art. 221 nouveau, 5), alinéa 2 (loi de finances rectificative 2026) — le taux zéro est également applicable aux prestations de services dont le lieu d''imposition est situé hors du Gabon, et qui ouvriraient droit à déduction si leur lieu d''imposition était au Gabon', 'G', null, 70, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lfr-2026', null, null, null, null),
  ('GA', 'GA-S-10', 'Taux réduit 10 %', '{}'::jsonb, 'Pièces détachées automobiles, essieux automobiles, carreaux de construction, pointes', 'percent', 10, 'sale', 'domestic', date '2016-01-01', null, 'Code général des impôts, art. 221 nouveau (LF 2016) — taux réduit de 10 % sur une liste de production et vente qui comprenait déjà les pièces détachées automobiles, essieux automobiles, carreaux de construction et pointes, aux côtés d''autres biens (eaux minérales locales, viandes et volailles importées, huile de table importée, sucre, arachide importée, lessive, fer à béton, ordinateurs, matériel de pêche, moteurs hors-bord, imperméables, conserves) ; art. 221 nouveau, 2) (loi de finances rectificative 2026) — la liste en vigueur depuis le 17 juillet 2026 ne retient plus, pour ce taux, que les quatre produits ci-dessus, les autres ayant été reclassés ailleurs', 'S', null, 30, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi-2019', null, null, null, null),
  ('GA', 'GA-S-18', 'Ventes de biens 18 %', '{}'::jsonb, 'Livraisons de biens au taux normal, TVA au compte 4431', 'percent', 18, 'sale', 'domestic', date '2016-01-01', null, 'Code général des impôts, art. 221 nouveau (LF 2016) — taux normal de 18 % applicable à toutes les opérations taxables à l''exclusion des opérations soumises au taux réduit ou au taux zéro ; toujours 18 % dans la rédaction de l''art. 221 nouveau, 1) de la loi de finances rectificative 2026, qui reformule seulement l''article pour viser les nouveaux taux réduits de 5 % et 3 %. Art. 212 et 213 — fait générateur et exigibilité à la livraison', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi-2019', null, null, null, null),
  ('GA', 'GA-S-18-SRV', 'Prestations de services 18 %, exigibles à l''encaissement', '{}'::jsonb, 'Prestations de services au taux normal, taxe due à l''encaissement du prix ou des acomptes', 'percent', 18, 'sale', 'domestic', date '2016-01-01', null, 'Code général des impôts, art. 221 nouveau (LF 2016) — le taux normal de 18 % couvre toutes les opérations taxables, prestations de services comprises ; art. 213 nouveau (LF 2015) — pour les prestations de services et les opérations réalisées avec l''État ou les collectivités locales, la taxe est exigible à l''encaissement du prix ou des acomptes, sauf autorisation d''acquitter la taxe d''après les débits, que ce pack ne retient pas par défaut. Facturée, la taxe attend l''encaissement au compte 4432 « T.V.A. facturée sur prestations de services » ; encaissée, elle est exigible et passe au compte 4431, dont l''intitulé « sur ventes » couvre aussi les ventes de services : le plan n''a pas de compte de taxe en attente propre aux services', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, true, '4432', 'cgi-2019', null, null, null, null),
  ('GA', 'GA-S-3', 'Taux réduit 3 %', '{}'::jsonb, 'Fer à béton fabriqué au Gabon — sous le plancher de 5 % de la directive TVA CEMAC', 'percent', 3, 'sale', 'domestic', date '2026-07-17', null, 'Code général des impôts, art. 221 nouveau, 4) (loi de finances rectificative 2026) — taux réduit de 3 % applicable aux opérations de production et de vente de fer à béton fabriqué au Gabon (l''importation n''est pas citée pour ce taux, à la différence des taux de 10 % et 5 %). Ce taux est sous le plancher de 5 % que fixe la directive CEMAC portant harmonisation des législations en matière de TVA du 10 novembre 2022, art. 22, 2°, c) pour les taux réduits (fourchette 5 % à 10 %) : un écart au cadre communautaire que ce pack se borne à consigner', 'S', null, 50, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lfr-2026', null, null, null, null),
  ('GA', 'GA-S-5', 'Taux réduit 5 %', '{}'::jsonb, 'Journaux et magazines importés, eau minérale importée', 'percent', 5, 'sale', 'domestic', date '2026-07-17', null, 'Code général des impôts, art. 221 nouveau, 3) (loi de finances rectificative 2026) — taux réduit de 5 % applicable aux opérations de production, d''importation et de vente de journaux et magazines importés et d''eau minérale importée. La loi de finances qui a introduit ce taux de 5 % (entre 2019 et 2025) n''a pas été retrouvée ; seule la rédaction du 17 juillet 2026 est citée ici', 'S', null, 40, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lfr-2026', null, null, null, null),
  ('GA', 'GA-S-EXO', 'Opération exonérée (art. 210)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2026-07-17', null, 'Code général des impôts, art. 210 nouveau (loi de finances rectificative 2026) — sont exonérés de la TVA, notamment, les opérations soumises à des taxations spécifiques exclusives (assurances et réassurances, intérêts d''emprunts extérieurs, jeux de hasard, mutations d''immeubles et de meubles incorporels, locations civiles de terrains non aménagés et locaux nus), les manuels scolaires, journaux et périodiques hors publicité, une liste de biens de première nécessité (laits, margarine, beurre, yaourts, sel, viandes et volailles importées, poissons, huiles de table locales, sucre, riz, conserves, pâtes, papier journal, cahiers et manuels scolaires, médicaments, produits pharmaceutiques, ciment, gravier, tôles, sable, eau minérale produite au Gabon), les véhicules électriques et, sous conditions, le gasoil de la pêche industrielle', 'E', null, 80, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lfr-2026', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
