update country_defaults set
  numbering_gapless             = true,
  number_format                 = '{CODE}/{YYYY}/{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Code général des impôts, art. P-832 ter, dans la rédaction de la loi de finances rectificative 2026 (art. 1) — toute opération d''un assujetti à la TVA fait l''objet d''une facture électronique normalisée délivrée par un dispositif électronique de facturation homologué par l''administration fiscale, porteur d''un numéro et d''un QR code qu''attribue le dispositif ; aucun texte trouvé ne fixe le format de ce numéro ni sa remise à zéro annuelle. Le format déclaré ici est celui de la pièce comptable interne, pas celui que le dispositif homologué attribuera.',
  numbering_source_key          = 'lfr-2026',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'delivery_date',
  tax_point_legal_reference     = 'Code général des impôts, art. 212 — le fait générateur se produit à la livraison pour les ventes, à l''exécution pour les prestations de services et travaux, à l''encaissement du prix pour les autres opérations ; art. 213 nouveau (LF 2015) — la taxe est exigible, pour les ventes et livraisons, lors de la réalisation du fait générateur, et pour les prestations de services et les opérations avec l''État ou les collectivités locales, à l''encaissement du prix ou des acomptes, sauf autorisation d''acquitter la taxe d''après les débits. delivery_date dit la règle des biens ; celle des prestations de services, à l''encaissement, est portée par les taxes de service de ce pack, en cash_basis, et non par un second fait générateur du pays.',
  tax_point_source_key          = 'cgi-2019',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Code général des impôts, art. P-832 ter, créé par la loi de finances pour 2026 et réécrit par la loi de finances rectificative 2026 (art. 1) — toute opération d''une personne soumise à l''impôt sur les sociétés, à l''impôt sur les bénéfices professionnels, à l''impôt synthétique libératoire ou assujettie à la TVA fait l''objet d''une facture électronique normalisée, délivrée au moyen d''un dispositif électronique de facturation homologué par l''administration fiscale, ou d''un document en tenant lieu admis par voie réglementaire ; un crédit d''impôt de 25 %, 25 % puis 50 % sur trois ans est accordé pour l''achat d''un dispositif physique. Art. 223 nouveau — seule la TVA figurant sur une facture électronique normalisée, ou un document en tenant lieu, est déductible. Le dispositif est nommé « E-Fact » par la DGI (page dgi.ga/e-fact/, injoignable depuis ce poste, connue seulement par un résumé de moteur de recherche, donc non retenue comme source). Aucun texte officiel lu ne fixe une date d''entrée en vigueur ni un calendrier de généralisation par catégorie de contribuable : une source secondaire (Deloitte, avril 2026) avance le 1er janvier 2026, non vérifiable ici. L''identifiant fiscal est le numéro d''identification fiscale (NIF, art. 232), sans code ISO 6523.',
  einvoice_source_key           = 'lfr-2026',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'GA';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('GA', 'exempt', 'exempt', 'Mention « exonérée » ou « prise en charge Etat », le cas échéant, par produit.', '{}'::jsonb, 10, date '1970-01-01', null, 'Textes fiscaux non codifiés annexés au Code général des impôts (contribution spéciale de solidarité), art. 28, 3° — la facture porte, par produit, la mention « exonérée » ou « prise en charge Etat » le cas échéant. L''article 248 nonies, créé par la loi de finances rectificative 2026, confirme que ce régime reste en vigueur en y soumettant aussi les plateformes numériques non-résidentes. Aucune disposition trouvée du chapitre de la TVA (art. 234 à 236) n''impose elle-même une mention de l''article d''exonération.')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
